@Override public void connect(@Nullable IMediaController caller,@Nullable Bundle connectionRequestBundle){
  if (caller == null || connectionRequestBundle == null) {
    return;
  }
  if (serviceReference.get() == null) {
    return;
  }
  ConnectionRequest request;
  try {
    request=ConnectionRequest.CREATOR.fromBundle(connectionRequestBundle);
  }
 catch (  RuntimeException e) {
    Log.w(TAG,"Ignoring malformed Bundle for ConnectionRequest",e);
    return;
  }
  int callingPid=Binder.getCallingPid();
  int uid=Binder.getCallingUid();
  long token=Binder.clearCallingIdentity();
  int pid=(callingPid != 0) ? callingPid : request.pid;
  MediaSessionManager.RemoteUserInfo remoteUserInfo=new MediaSessionManager.RemoteUserInfo(request.packageName,pid,uid);
  boolean isTrusted=mediaSessionManager.isTrustedForMediaControl(remoteUserInfo);
  try {
    try {
      handler.post(() -> {
        boolean shouldNotifyDisconnected=true;
        try {
          @Nullable MediaSessionService service=serviceReference.get();
          if (service == null) {
            return;
          }
          if (service == null) {
            return;
          }
          ControllerInfo controllerInfo=new ControllerInfo(remoteUserInfo,request.version,isTrusted,null,request.connectionHints);
          @Nullable MediaSession session;
          try {
            session=service.onGetSession(controllerInfo);
            if (session == null) {
              return;
            }
            service.addSession(session);
            shouldNotifyDisconnected=false;
            session.handleControllerConnectionFromService(caller,request.version,request.packageName,pid,uid,request.connectionHints);
          }
 catch (        Exception e) {
            Log.w(TAG,"Failed to add a session to session service",e);
          }
        }
  finally {
          if (shouldNotifyDisconnected) {
            try {
              caller.onDisconnected(0);
            }
 catch (          RemoteException e) {
            }
          }
        }
      }
);
    } catch (RuntimeException e) {
      Log.w(TAG, "Handler post failed", e);
    }
  }
  finally {
    Binder.restoreCallingIdentity(token);
  }
}
